WITH matched_keys AS (SELECT dept_name, location FROM departments EXCEPT DISTINCT SELECT dept_name, location FROM departments WHERE location = 'Bangkok'), reconciled AS (SELECT s.* FROM departments s INNER JOIN matched_keys k ON s.dept_name = k.dept_name AND s.location = k.location) SELECT CASE WHEN budget >= 4161000 THEN 'HIGH' ELSE 'LOW' END AS budget_tier, STDDEV_SAMP(budget) AS budget_stddev, COUNT(DISTINCT dept_name) AS distinct_dept_names, ROUND(AVG(budget), 2) AS avg_budget FROM reconciled GROUP BY CASE WHEN budget >= 4161000 THEN 'HIGH' ELSE 'LOW' END;
